INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('iphone-16-standard', 'iphone-16', 'iphone', 'iPhone 16', 'iPhone 16', '6.1"', '147.6 x 71.6 x 7.80 มม.', '170 กรัม', 'ชิป A18 พร้อม CPU แบบ 6-core (2 ประสิทธิภาพ + 4 ประหยัดพลังงาน), GPU แบบ 5-core และ Neural Engine แบบ 16-core', 'จอภาพ Super Retina XDR OLED ขนาด 6.1 นิ้ว (แนวทแยง), ความละเอียด 2556 x 1179 พิกเซลที่ 460 ppi, ความสว่างสูงสุด 2,000 นิต (กลางแจ้ง), Dynamic Island, คอนทราสต์เรโช 2,000,000:1', 'ระบบกล้องคู่ขั้นสูง: กล้อง Fusion 48MP (26 มม., ƒ/1.6, ระบบ OIS แบบเลื่อนเซ็นเซอร์) + กล้อง Ultra Wide 12MP (13 มม., ƒ/2.2, มุมมอง 120°), ภาพถ่ายความละเอียดสูงพิเศษ (24MP และ 48MP), ปุ่มควบคุมกล้อง (Camera Control)', 'การเล่นวิดีโอนานสูงสุด 22 ชั่วโมง, การเล่นเสียงนานสูงสุด 80 ชั่วโมง, รองรับการชาร์จเร็วสูงสุด 50% ใน 30 นาที ด้วยอะแดปเตอร์ 20W หรือสูงกว่า', 'iPhone 16 พร้อม iOS 18, สายชาร์จ USB-C (1 ม., รองรับ 60W), เอกสารประกอบ', '5G (sub-6 GHz), Wi-Fi 7 (802.11be), Bluetooth 5.3, ชิป Ultra Wideband รุ่นที่ 2, พอร์ต USB-C รองรับ USB 2', 'กระจกแต่งสีด้านหลังและกรอบอะลูมิเนียมเกรดเดียวกับที่ใช้ในอุตสาหกรรมอวกาศ, ด้านหน้าแบบ Ceramic Shield รุ่นล่าสุด', 29900, 41900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-finish-select-202409-6-1inch-ultramarine?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-finish-select-202409-6-1inch-ultramarine?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-iphone/iphone-16', 'https://www.apple.com/th/iphone-16/specs/', 'https://www.apple.com/th/iphone-16/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('iphone-16-plus', 'iphone-16', 'iphone', 'iPhone 16 Plus', 'iPhone 16 Plus', '6.7"', '160.9 x 77.8 x 7.80 มม.', '199 กรัม', 'ชิป A18 พร้อม CPU แบบ 6-core (2 ประสิทธิภาพ + 4 ประหยัดพลังงาน), GPU แบบ 5-core และ Neural Engine แบบ 16-core', 'จอภาพ Super Retina XDR OLED ขนาด 6.7 นิ้ว (แนวทแยง), ความละเอียด 2796 x 1290 พิกเซลที่ 460 ppi, ความสว่างสูงสุด 2,000 นิต (กลางแจ้ง), Dynamic Island, คอนทราสต์เรโช 2,000,000:1', 'ระบบกล้องคู่ขั้นสูง: กล้อง Fusion 48MP (26 มม., ƒ/1.6) + กล้อง Ultra Wide 12MP (13 มม., ƒ/2.2), รองรับภาพถ่ายมาโคร, ปุ่มควบคุมกล้อง (Camera Control)', 'การเล่นวิดีโอนานสูงสุด 27 ชั่วโมง, การเล่นเสียงนานสูงสุด 100 ชั่วโมง, รองรับการชาร์จเร็วสูงสุด 50% ใน 30 นาที', 'iPhone 16 Plus พร้อม iOS 18, สายชาร์จ USB-C (1 ม.), เอกสารประกอบ', '5G (sub-6 GHz), Wi-Fi 7, Bluetooth 5.3, ชิป Ultra Wideband รุ่นที่ 2, พอร์ต USB-C', 'กระจกแต่งสีด้านหลังและกรอบอะลูมิเนียมเกรดเดียวกับที่ใช้ในอุตสาหกรรมอวกาศ, ด้านหน้าแบบ Ceramic Shield รุ่นล่าสุด', 34900, 46900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-finish-select-202409-6-1inch-ultramarine?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-finish-select-202409-6-1inch-ultramarine?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-iphone/iphone-16', 'https://www.apple.com/th/iphone-16/specs/', 'https://www.apple.com/th/iphone-16/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('iphone-16-pro', 'iphone-16-pro', 'iphone', 'iPhone 16 Pro', 'iPhone 16 Pro', '6.3"', '149.6 x 71.5 x 8.25 มม.', '199 กรัม', 'ชิป A18 Pro พร้อม CPU แบบ 6-core (2 ประสิทธิภาพ + 4 ประหยัดพลังงาน), GPU แบบ 6-core ระดับโปร และ Neural Engine แบบ 16-core', 'จอภาพ Super Retina XDR OLED ขนาด 6.3 นิ้ว, เทคโนโลยี ProMotion อัตรารีเฟรชสูงสุด 120Hz, ความละเอียด 2622 x 1206 พิกเซลที่ 460 ppi, จอภาพติดตลอด (Always-On)', 'ระบบกล้องระดับโปร: กล้อง Fusion 48MP (24 มม., ƒ/1.78) + กล้อง Ultra Wide 48MP (13 มม., ƒ/2.2) + กล้อง Telephoto 5x 12MP (120 มม., ƒ/2.8), สแกนเนอร์ LiDAR, บันทึกวิดีโอ 4K Dolby Vision 120 fps, ปุ่มควบคุมกล้อง (Camera Control)', 'การเล่นวิดีโอนานสูงสุด 27 ชั่วโมง, การเล่นสตรีมวิดีโอนานสูงสุด 22 ชั่วโมง, ชาร์จเร็ว 50% ใน 30 นาที', 'iPhone 16 Pro พร้อม iOS 18, สายชาร์จ USB-C (1 ม., รองรับ USB 3), เอกสารประกอบ', '5G, Wi-Fi 7, Bluetooth 5.3, Ultra Wideband 2, Thread, พอร์ต USB-C รองรับ USB 3 (สูงสุด 10Gb/s)', 'ดีไซน์ไทเทเนียมเกรด 5 ผิวขัดเงาละเอียด ด้านหลังกระจกผิวด้านแบบมีสีในตัว ด้านหน้า Ceramic Shield รุ่นล่าสุด', 39900, 59900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-pro-finish-select-202409-6-3inch-deserttitanium?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-pro-finish-select-202409-6-3inch-deserttitanium?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-iphone/iphone-16-pro', 'https://www.apple.com/th/iphone-16-pro/specs/', 'https://www.apple.com/th/iphone-16-pro/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('iphone-16-pro-max', 'iphone-16-pro', 'iphone', 'iPhone 16 Pro Max', 'iPhone 16 Pro Max', '6.9"', '163.0 x 77.6 x 8.25 มม.', '227 กรัม', 'ชิป A18 Pro พร้อม CPU แบบ 6-core (2 ประสิทธิภาพ + 4 ประหยัดพลังงาน), GPU แบบ 6-core ระดับโปร และ Neural Engine แบบ 16-core', 'จอภาพ Super Retina XDR OLED ขนาด 6.9 นิ้ว, เทคโนโลยี ProMotion อัตรารีเฟรช 1-120Hz, ความละเอียด 2868 x 1320 พิกเซลที่ 460 ppi, จอภาพติดตลอด (Always-On)', 'ระบบกล้องระดับโปร: กล้อง Fusion 48MP + กล้อง Ultra Wide 48MP + กล้อง Telephoto 5x 12MP (120 มม., ดีไซน์เตตร้าปริซึม), ซูมแบบออปติคัล 5 เท่า, สแกนเนอร์ LiDAR, ปุ่มควบคุมกล้อง (Camera Control)', 'การเล่นวิดีโอนานสูงสุด 33 ชั่วโมง (แบตเตอรี่อึดที่สุดในประวัติศาสตร์ iPhone), การเล่นเสียงนานสูงสุด 105 ชั่วโมง', 'iPhone 16 Pro Max พร้อม iOS 18, สายชาร์จ USB-C (1 ม., รองรับ USB 3), เอกสารประกอบ', '5G, Wi-Fi 7, Bluetooth 5.3, Ultra Wideband 2, Thread, พอร์ต USB-C รองรับ USB 3 (สูงสุด 10Gb/s)', 'ดีไซน์ไทเทเนียมเกรด 5 ผิวขัดเงา ด้านหลังกระจกผิวด้านแบบมีสีในตัว ด้านหน้า Ceramic Shield', 48900, 64900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-pro-finish-select-202409-6-3inch-deserttitanium?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-16-pro-finish-select-202409-6-3inch-deserttitanium?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-iphone/iphone-16-pro', 'https://www.apple.com/th/iphone-16-pro/specs/', 'https://www.apple.com/th/iphone-16-pro/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('iphone-15', 'iphone-15', 'iphone', 'iPhone 15', 'iPhone 15', '6.1"', '147.6 x 71.6 x 7.80 มม.', '171 กรัม', 'ชิป A16 Bionic พร้อม CPU แบบ 6-core (2 ประสิทธิภาพ + 4 ประหยัดพลังงาน), GPU แบบ 5-core และ Neural Engine แบบ 16-core', 'จอภาพ Super Retina XDR OLED ขนาด 6.1 นิ้ว, ความละเอียด 2556 x 1179 พิกเซลที่ 460 ppi, Dynamic Island, ความสว่างสูงสุด 2,000 นิต (กลางแจ้ง)', 'ระบบกล้องคู่ขั้นสูง: กล้องหลัก 48MP (26 มม., ƒ/1.6) + กล้อง Ultra Wide 12MP (13 มม., ƒ/2.4), ถ่ายภาพบุคคลรุ่นถัดไปพร้อมการควบคุมโฟกัสและความชัดลึก', 'การเล่นวิดีโอนานสูงสุด 20 ชั่วโมง, การเล่นเสียงนานสูงสุด 80 ชั่วโมง, ชาร์จเร็ว 50% ใน 30 นาที', 'iPhone 15 พร้อม iOS, สายชาร์จ USB-C (1 ม.), เอกสารประกอบ', '5G, Wi-Fi 6, Bluetooth 5.3, ชิป Ultra Wideband รุ่นที่ 2, พอร์ต USB-C', 'ด้านหลังแบบกระจกแต่งสี และดีไซน์อะลูมิเนียม ด้านหน้า Ceramic Shield', 26900, 38900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-15-finish-select-202309-6-1inch-pink?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-15-finish-select-202309-6-1inch-pink?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-iphone/iphone-15', 'https://www.apple.com/th/iphone-15/specs/', 'https://www.apple.com/th/iphone-15/');
