INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('iphone-se-3', 'iphone-se', 'iphone', 'iPhone SE (รุ่นที่ 3)', 'iPhone SE (3rd Gen)', '4.7"', '138.4 x 67.3 x 7.3 มม.', '144 กรัม', 'ชิป A15 Bionic พร้อม CPU แบบ 6-core, GPU แบบ 4-core และ Neural Engine แบบ 16-core', 'จอภาพ Retina HD LCD ขนาด 4.7 นิ้ว, ความละเอียด 1334 x 750 พิกเซลที่ 326 ppi, ปุ่มโฮมพร้อม Touch ID', 'กล้องไวด์ 12MP (ƒ/1.8), HDR อัจฉริยะ 4, วิดีโอ 4K สูงสุด 60 fps', 'การเล่นวิดีโอนานสูงสุด 15 ชั่วโมง, ชาร์จเร็ว 50% ใน 30 นาที', 'iPhone SE พร้อม iOS, สาย USB-C เป็น Lightning (1 ม.), เอกสารประกอบ', '5G, Wi-Fi 6, Bluetooth 5.0, พอร์ต Lightning', 'ดีไซน์กระจกและอะลูมิเนียม', 17900, 23900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-se-finish-select-202207-midnight?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/iphone-se-finish-select-202207-midnight?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-iphone/iphone-se', 'https://www.apple.com/th/iphone-se/specs/', 'https://www.apple.com/th/iphone-se/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('ipad-pro-11-m4', 'ipad-pro', 'ipad', 'iPad Pro รุ่น 11 นิ้ว (M4)', 'iPad Pro 11-inch (M4)', '11"', '249.7 x 177.5 x 5.3 มม.', '444 กรัม (Wi-Fi) / 446 กรัม (Cellular)', 'ชิป M4 พร้อม CPU สูงสุดแบบ 10-core, GPU แบบ 10-core รองรับ Ray Tracing ด้วยฮาร์ดแวร์ และ Neural Engine แบบ 16-core (38 ล้านล้านคำสั่งต่อวินาที)', 'จอภาพ Ultra Retina XDR เทคโนโลยี Tandem OLED สองชั้น, ความละเอียด 2420 x 1668 พิกเซลที่ 264 ppi, ProMotion 10-120Hz, ความสว่างเต็มหน้าจอ 1,000 นิต (XDR สูงสุด 1,600 นิต), ตัวเลือกกระจก Nano-texture สำหรับรุ่น 1TB/2TB', 'กล้องไวด์ 12MP (ƒ/1.8), ซูมดิจิทัล 5x, แฟลช True Tone แบบปรับตามสภาวะ, สแกนเนอร์ LiDAR, กล้องหน้าแนวนอน Ultra Wide 12MP พร้อมคุณสมบัติจัดให้อยู่ตรงกลาง (Center Stage)', 'ท่องเว็บผ่าน Wi-Fi หรือดูวิดีโอนานสูงสุด 10 ชั่วโมง, ชาร์จผ่านอะแดปเตอร์แปลงไฟหรือ USB-C เข้ากับระบบคอมพิวเตอร์', 'iPad Pro 11 นิ้ว, สายชาร์จ USB-C (1 ม.), อะแดปเตอร์แปลงไฟ USB-C ขนาด 20W, ผ้าเช็ดหน้าจอ (เฉพาะรุ่นกระจก Nano-texture)', 'Thunderbolt / USB 4 (สูงสุด 40Gb/s), Wi-Fi 6E (802.11ax), Bluetooth 5.3, ตัวเลือก 5G (eSIM)', 'ตัวเครื่องอะลูมิเนียมรีไซเคิล 100% ดีไซน์บางเฉียบที่สุดเท่าที่ Apple เคยสร้างมาเพียง 5.3 มม.', 39900, 87900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/ipad-pro-finish-select-202405-11inch-spaceblack?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/ipad-pro-finish-select-202405-11inch-spaceblack?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-ipad/ipad-pro', 'https://www.apple.com/th/ipad-pro/specs/', 'https://www.apple.com/th/ipad-pro/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('ipad-pro-13-m4', 'ipad-pro', 'ipad', 'iPad Pro รุ่น 13 นิ้ว (M4)', 'iPad Pro 13-inch (M4)', '13"', '281.6 x 215.5 x 5.1 มม.', '579 กรัม (Wi-Fi) / 582 กรัม (Cellular)', 'ชิป M4 พร้อม CPU สูงสุดแบบ 10-core, GPU แบบ 10-core รองรับ Ray Tracing และ Neural Engine แบบ 16-core', 'จอภาพ Ultra Retina XDR Tandem OLED ขนาด 13 นิ้ว, ความละเอียด 2752 x 2064 พิกเซลที่ 264 ppi, ProMotion 10-120Hz, ความสว่าง XDR สูงสุด 1,600 นิต, บางเฉียบที่สุดในประวัติศาสตร์ Apple เพียง 5.1 มม.', 'กล้องไวด์ 12MP + LiDAR + กล้องหน้า Ultra Wide แนวนอน 12MP รองรับ Center Stage', 'ท่องเว็บผ่าน Wi-Fi หรือดูวิดีโอนานสูงสุด 10 ชั่วโมง', 'iPad Pro 13 นิ้ว, สายชาร์จ USB-C (1 ม.), อะแดปเตอร์แปลงไฟ USB-C 20W, ผ้าเช็ดหน้าจอ (สำหรับกระจก Nano-texture)', 'Thunderbolt / USB 4, Wi-Fi 6E, Bluetooth 5.3, ตัวเลือก 5G (eSIM)', 'ตัวเรือนอะลูมิเนียมรีไซเคิล 100% บางที่สุดเพียง 5.1 มม.', 52900, 100900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/ipad-pro-finish-select-202405-11inch-spaceblack?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/ipad-pro-finish-select-202405-11inch-spaceblack?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-ipad/ipad-pro', 'https://www.apple.com/th/ipad-pro/specs/', 'https://www.apple.com/th/ipad-pro/');
