INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('macbook-pro-14', 'macbook-pro', 'mac', 'MacBook Pro 14 นิ้ว (M4 / M4 Pro / M4 Max)', 'MacBook Pro 14-inch (M4 / M4 Pro / M4 Max)', '14.2"', '312.6 x 221.2 x 15.5 มม.', '1,550 กรัม (M4) / 1,600 กรัม (M4 Pro/Max)', 'ชิป M4 (CPU 10-core, GPU 10-core) หรือ M4 Pro (CPU สูงสุด 14-core, GPU สูงสุด 20-core) หรือ M4 Max (CPU สูงสุด 16-core, GPU สูงสุด 40-core)', 'จอภาพ Liquid Retina XDR ขนาด 14.2 นิ้ว, ความละเอียด 3024 x 1964 พิกเซลที่ 254 ppi, ProMotion 120Hz, ความสว่าง SDR สูงสุด 1,000 นิต, XDR สูงสุด 1,600 นิต, ตัวเลือกกระจก Nano-texture', 'กล้อง 12MP Center Stage รองรับ Desk View และวิดีโอ 1080p HD, ระบบเสียง 6 ลำโพงพร้อมวูฟเฟอร์ตัดแรงสั่นสะเทือน', 'เล่นวิดีโอนานสูงสุด 24 ชั่วโมง (M4) / สูงสุด 22 ชั่วโมง (M4 Pro/Max), ท่องเว็บแบบไร้สายสูงสุด 16 ชั่วโมง, ชาร์จเร็วผ่านอะแดปเตอร์ 70W หรือ 96W', 'MacBook Pro 14 นิ้ว, สาย USB-C เป็น MagSafe 3 (2 ม.), อะแดปเตอร์แปลงไฟ USB-C ขนาด 70W (สำหรับ M4) หรือ 96W (สำหรับ M4 Pro)', 'พอร์ต Thunderbolt 4 (M4) หรือ Thunderbolt 5 สูงสุด 120Gb/s (M4 Pro/Max) จำนวน 3 พอร์ต, ช่องเสียบการ์ด SDXC, พอร์ต HDMI รองรับ 8K, ช่องต่อหูฟัง 3.5 มม., พอร์ต MagSafe 3, Wi-Fi 6E, Bluetooth 5.3', 'ตัวเครื่องอะลูมิเนียมชิ้นเดียว (Unibody) รีไซเคิล 100% พร้อมระบบระบายความร้อนอันล้ำสมัย', 54900, 112900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mbp14-spaceblack-select-202410?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mbp14-spaceblack-select-202410?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/macbook-pro', 'https://www.apple.com/th/macbook-pro/specs/', 'https://www.apple.com/th/macbook-pro/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('macbook-pro-16', 'macbook-pro', 'mac', 'MacBook Pro 16 นิ้ว (M4 Pro / M4 Max)', 'MacBook Pro 16-inch (M4 Pro / M4 Max)', '16.2"', '355.7 x 248.1 x 16.8 มม.', '2,140 กรัม (M4 Pro) / 2,150 กรัม (M4 Max)', 'ชิป M4 Pro หรือ M4 Max ระดับสุดยอดโปร สำหรับเวิร์กโฟลว์ระดับภาพยนตร์และ AI ขั้นสูง', 'จอภาพ Liquid Retina XDR ขนาด 16.2 นิ้ว, ความละเอียด 3456 x 2234 พิกเซลที่ 254 ppi, ProMotion 120Hz, ความสว่าง XDR 1,600 นิต, ตัวเลือกกระจก Nano-texture', 'กล้อง 12MP Center Stage พร้อม Desk View, ระบบเสียง 6 ลำโพงความเที่ยงตรงสูงระดับสตูดิโอ', 'เล่นวิดีโอนานสูงสุด 24 ชั่วโมง (แบตเตอรี่ที่ยาวนานที่สุดใน Mac ทุกรุ่น), รองรับอะแดปเตอร์แปลงไฟ USB-C 140W', 'MacBook Pro 16 นิ้ว, สาย USB-C เป็น MagSafe 3 (2 ม.), อะแดปเตอร์แปลงไฟ USB-C 140W', 'Thunderbolt 5 (สูงสุด 120Gb/s) x 3, ช่องเสียบการ์ด SDXC, พอร์ต HDMI 8K, MagSafe 3, Wi-Fi 6E', 'ตัวเรือนอะลูมิเนียม Unibody พร้อมชั้นอะโนไดซ์ลดรอยนิ้วมือ', 89900, 138900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mbp14-spaceblack-select-202410?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mbp14-spaceblack-select-202410?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/macbook-pro', 'https://www.apple.com/th/macbook-pro/specs/', 'https://www.apple.com/th/macbook-pro/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('macbook-air-13', 'macbook-air', 'mac', 'MacBook Air 13 นิ้ว (M3)', 'MacBook Air 13-inch (M3)', '13.6"', '304.1 x 215.0 x 11.3 มม.', '1,240 กรัม', 'ชิป M3 พร้อม CPU แบบ 8-core (4 ประสิทธิภาพ + 4 ประหยัดพลังงาน), GPU สูงสุด 10-core รองรับ Ray Tracing และ Neural Engine แบบ 16-core, หน่วยความจำเริ่มต้นมาตรฐาน 16GB', 'จอภาพ Liquid Retina ขนาด 13.6 นิ้ว, ความละเอียด 2560 x 1664 พิกเซลที่ 224 ppi, ความสว่าง 500 นิต, ขอบเขตสีกว้าง P3, รองรับจอภาพภายนอกสูงสุด 2 จอ (เมื่อปิดฝาพับ)', 'กล้อง FaceTime HD 1080p, ระบบเสียง 4 ลำโพงพร้อมระบบเสียงตามตำแหน่ง Spatial Audio', 'เล่นวิดีโอนานสูงสุด 18 ชั่วโมง, ท่องเว็บไร้สายนานสูงสุด 15 ชั่วโมง', 'MacBook Air 13 นิ้ว, สาย USB-C เป็น MagSafe 3 (2 ม.), อะแดปเตอร์แปลงไฟ USB-C ขนาด 30W หรือพอร์ตคู่ 35W', 'พอร์ต MagSafe 3, พอร์ต Thunderbolt / USB 4 จำนวน 2 พอร์ต, ช่องต่อหูฟัง 3.5 มม., Wi-Fi 6E, Bluetooth 5.3', 'ตัวเรือนอะลูมิเนียมแบบไร้พัดลม เงียบสนิท 100% พร้อมการเคลือบผิวอะโนไดซ์ลดรอยนิ้วมือสำหรับสีมิดไนท์', 39900, 53900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mba13-midnight-select-202402?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mba13-midnight-select-202402?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/macbook-air', 'https://www.apple.com/th/macbook-air/specs/', 'https://www.apple.com/th/macbook-air/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('macbook-air-15', 'macbook-air', 'mac', 'MacBook Air 15 นิ้ว (M3)', 'MacBook Air 15-inch (M3)', '15.3"', '340.4 x 237.6 x 11.5 มม.', '1,510 กรัม', 'ชิป M3 พร้อม CPU แบบ 8-core, GPU แบบ 10-core และ Neural Engine แบบ 16-core, หน่วยความจำเริ่มต้นมาตรฐาน 16GB', 'จอภาพ Liquid Retina ขนาด 15.3 นิ้ว, ความละเอียด 2880 x 1864 พิกเซลที่ 224 ppi, ความสว่าง 500 นิต', 'กล้อง FaceTime HD 1080p, ระบบเสียง 6 ลำโพงพร้อมวูฟเฟอร์ตัดแรงสั่นสะเทือน', 'เล่นวิดีโอนานสูงสุด 18 ชั่วโมง', 'MacBook Air 15 นิ้ว, สาย USB-C เป็น MagSafe 3 (2 ม.), อะแดปเตอร์แปลงไฟ USB-C ขนาดกะทัดรัดแบบพอร์ตคู่ 35W', 'MagSafe 3, Thunderbolt / USB 4 x 2, ช่องต่อหูฟัง 3.5 มม., Wi-Fi 6E', 'ตัวเรือนอะลูมิเนียมบางเฉียบเพียง 11.5 มม. ทำงานเงียบสนิทไร้พัดลม', 47900, 61900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mba13-midnight-select-202402?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mba13-midnight-select-202402?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/macbook-air', 'https://www.apple.com/th/macbook-air/specs/', 'https://www.apple.com/th/macbook-air/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('imac-24-m4', 'imac', 'mac', 'iMac 24 นิ้ว (M4)', 'iMac 24-inch (M4)', '24"', '547 x 461 x 147 มม.', '4,420 กรัม (รุ่น 2 พอร์ต) / 4,440 กรัม (รุ่น 4 พอร์ต)', 'ชิป M4 พร้อม CPU แบบ 8-core หรือ 10-core, GPU แบบ 8-core หรือ 10-core และ Neural Engine แบบ 16-core, หน่วยความจำเริ่มต้น 16GB', 'จอภาพ 4.5K Retina ขนาด 24 นิ้ว, ความละเอียด 4480 x 2520 พิกเซลที่ 218 ppi, ความสว่าง 500 นิต, แสดงผลได้กว่า 1 พันล้านสี, มีตัวเลือกกระจก Nano-texture', 'กล้อง 12MP Center Stage รองรับ Desk View และวิดีโอ 1080p HD, ระบบเสียง 6 ลำโพงพร้อมระบบตัดเสียงสะท้อนระดับสตูดิโอ', 'ใช้ไฟกระแสสลับ 100-240V AC ผ่านอะแดปเตอร์แปลงไฟ 143W พร้อมพอร์ต Gigabit Ethernet', 'iMac 24 นิ้ว, Magic Keyboard พร้อม Touch ID (ตามรุ่น), Magic Mouse, อะแดปเตอร์แปลงไฟ 143W, สายไฟ (2 ม.), สาย USB-C เป็น USB-C', 'Thunderbolt 4 / USB 4 จำนวน 2 หรือ 4 พอร์ต, Gigabit Ethernet, ช่องต่อหูฟัง 3.5 มม., Wi-Fi 6E, Bluetooth 5.3', 'ดีไซน์บางเฉียบเพียง 11.5 มม. โครงสร้างอะลูมิเนียมชุบผิวหลากสีสันสดใส', 44900, 65900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/imac-touch-id-blue-selection-hero-202410?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/imac-touch-id-blue-selection-hero-202410?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/imac', 'https://www.apple.com/th/imac/specs/', 'https://www.apple.com/th/imac/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('mac-mini-m4', 'mac-mini', 'mac', 'Mac mini (M4 / M4 Pro)', 'Mac mini (M4 / M4 Pro)', 'Desktop', '127.0 x 127.0 x 50.0 มม.', '670 กรัม (M4) / 730 กรัม (M4 Pro)', 'ชิป M4 (CPU 10-core, GPU 10-core) หรือชิป M4 Pro (CPU 12/14-core, GPU 16/20-core), หน่วยความจำเริ่มต้น 16GB (M4) หรือ 24GB (M4 Pro)', 'รองรับจอภาพภายนอกสูงสุด 3 จอ (สูงสุดความละเอียด 8K 60Hz หรือ 4K 240Hz ผ่าน HDMI)', 'ไม่มีในตัว (รองรับ Continuity Camera ผ่าน iPhone หรือกล้องเว็บแคม USB)', 'ใช้ไฟบ้านผ่านสายไฟ AC โดยตรง กำลังไฟสูงสุด 150W ต่อเนื่อง', 'Mac mini, สายไฟ AC (1.8 ม.)', 'ด้านหน้า: พอร์ต USB-C (USB 3) x 2, ช่องหูฟัง 3.5 มม. / ด้านหลัง: Thunderbolt 4 (M4) หรือ Thunderbolt 5 (M4 Pro) x 3, HDMI, Gigabit Ethernet (อัปเกรด 10Gb ได้), Wi-Fi 6E, Bluetooth 5.3', 'ตัวเครื่องอะลูมิเนียมกะทัดรัดขนาดเพียง 5 x 5 นิ้ว ถือเป็นผลิตภัณฑ์ Carbon Neutral รุ่นแรกของ Mac', 20900, 49900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mac-mini-select-202410?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mac-mini-select-202410?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/mac-mini', 'https://www.apple.com/th/mac-mini/specs/', 'https://www.apple.com/th/mac-mini/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('mac-studio-m2', 'mac-studio', 'mac', 'Mac Studio (M2 Max / M2 Ultra)', 'Mac Studio (M2 Max / M2 Ultra)', 'Desktop', '197.0 x 197.0 x 95.0 มม.', '2,700 กรัม (M2 Max) / 3,600 กรัม (M2 Ultra)', 'ชิป M2 Max (CPU 12-core, GPU 30/38-core) หรือ M2 Ultra (CPU 24-core, GPU 60/76-core, Neural Engine 32-core)', 'รองรับจอภาพภายนอกสูงสุด 8 จอภาพพร้อมกัน', 'ไม่มีในตัว (รองรับกล้องสตูดิโอและ Continuity Camera)', 'ใช้ไฟบ้าน กำลังไฟสูงสุด 370W', 'Mac Studio, สายไฟ AC', 'Thunderbolt 4 x 4 (M2 Max) หรือ x 6 (M2 Ultra), USB-A x 2, HDMI, 10Gb Ethernet, ช่องใส่ SDXC ด้านหน้า', 'ตัวเครื่องอะลูมิเนียมชิ้นเดียวพร้อมระบบพัดลมคู่แบบหมุนเวียนคู่ขนาน', 74900, 149900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mac-studio-select-202306?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mac-studio-select-202306?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-mac/mac-studio', 'https://www.apple.com/th/mac-studio/specs/', 'https://www.apple.com/th/mac-studio/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('apple-watch-s10-42', 'apple-watch-series-10', 'watch', 'Apple Watch Series 10 (42 มม.)', 'Apple Watch Series 10 (42mm)', '42mm', '42.0 x 36.0 x 9.7 มม.', '30.0 กรัม (อะลูมิเนียม) / 34.4 กรัม (ไทเทเนียม)', 'ชิป S10 SiP พร้อมโปรเซสเซอร์แบบ 64-bit 2-core และ Neural Engine แบบ 4-core', 'จอภาพ OLED แบบ Wide-angle ที่มุมมองกว้างขึ้น สว่างขึ้นเมื่อมองจากมุมเฉียงสูงสุด 40%, ความสว่างสูงสุด 2,000 นิต, หนาเพียง 9.7 มม. (บางลง 10%)', 'ไม่มีในตัว (รองรับรีโมทควบคุมกล้อง iPhone)', 'ใช้งานได้นานสูงสุด 18 ชั่วโมง (โหมดประหยัดพลังงานสูงสุด 36 ชั่วโมง), ชาร์จเร็ว 80% ได้ในเวลาเพียง 30 นาที', 'ตัวเรือน Apple Watch Series 10 (42 มม.), สายนาฬิกาตามแบบที่เลือก, สายชาร์จเร็วแบบแม่เหล็กเป็น USB-C (1 ม.)', 'GPS หรือ GPS + Cellular (4G LTE), Wi-Fi 4 (802.11n), Bluetooth 5.3, ชิป Ultra Wideband รุ่นที่ 2', 'มีให้เลือกทั้งอะลูมิเนียมขัดเงา (ดำเจ็ทแบล็ค) หรือไทเทเนียมเกรดอากาศยานขัดเงา กระจกหน้าจอ Sapphire Crystal', 14900, 25900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-42-aluminum-jetblack-nc-s10?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-42-aluminum-jetblack-nc-s10?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-watch/apple-watch', 'https://www.apple.com/th/apple-watch-series-10/specs/', 'https://www.apple.com/th/apple-watch-series-10/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('apple-watch-s10-46', 'apple-watch-series-10', 'watch', 'Apple Watch Series 10 (46 มม.)', 'Apple Watch Series 10 (46mm)', '46mm', '46.0 x 39.0 x 9.7 มม.', '36.4 กรัม (อะลูมิเนียม) / 41.7 กรัม (ไทเทเนียม)', 'ชิป S10 SiP พร้อม Neural Engine แบบ 4-core', 'จอภาพ OLED แบบ Wide-angle พื้นที่หน้าจอใหญ่กว่า Series 6 ถึงเกือบ 30%, ความสว่างสูงสุด 2,000 นิต', 'ไม่มีในตัว (รองรับรีโมทควบคุมกล้อง iPhone)', 'ใช้งานปกติสูงสุด 18 ชั่วโมง (โหมดประหยัดพลังงานสูงสุด 36 ชั่วโมง), ชาร์จเร็ว 80% ใน 30 นาที', 'ตัวเรือน Apple Watch Series 10 (46 มม.), สายนาฬิกา, สายชาร์จเร็วแบบแม่เหล็กเป็น USB-C (1 ม.)', 'GPS หรือ GPS + Cellular, Wi-Fi, Bluetooth 5.3, Ultra Wideband 2', 'ตัวเรือนอะลูมิเนียม หรือไทเทเนียมเกรด 5 พร้อมหน้าปัดกระจกแซฟไฟร์', 15900, 27900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-42-aluminum-jetblack-nc-s10?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-42-aluminum-jetblack-nc-s10?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-watch/apple-watch', 'https://www.apple.com/th/apple-watch-series-10/specs/', 'https://www.apple.com/th/apple-watch-series-10/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('apple-watch-ultra-2', 'apple-watch-ultra-2', 'watch', 'Apple Watch Ultra 2 (49 มม.)', 'Apple Watch Ultra 2 (49mm)', '49mm', '49.0 x 44.0 x 14.4 มม.', '61.4 กรัม (ไทเทเนียมธรรมชาติ) / 61.8 กรัม (ไทเทเนียมดำ)', 'ชิป S9 SiP พร้อมโปรเซสเซอร์ 64-bit แบบ 2-core และ Neural Engine แบบ 4-core, คำสั่งนิ้ว ''แตะสองครั้ง'' (Double Tap)', 'จอภาพ Always-On Retina LTPO OLED ความสว่างสูงสุดถึง 3,000 นิต (สว่างที่สุดในบรรดาอุปกรณ์พกพา Apple ทั้งหมด), ความสว่างต่ำสุด 1 นิตในที่มืด, ผลึกแซฟไฟร์แบนเรียบพร้อมขอบยกสูงป้องกันแรงกระแทก', 'ไม่มีในตัว (รองรับรีโมทควบคุมกล้อง iPhone)', 'การใช้งานปกติสูงสุด 36 ชั่วโมง, ในโหมดประหยัดพลังงานสูงสุด 72 ชั่วโมง, ใช้งานกิจกรรมกลางแจ้งพร้อม GPS และวัดอัตราการเต้นของหัวใจสูงสุด 17 ชั่วโมง', 'Apple Watch Ultra 2, สายนาฬิกา (Trail Loop, Alpine Loop, หรือ Ocean Band), สายชาร์จเร็วแบบแม่เหล็กเป็น USB-C แบบถัก (1 ม.)', 'GPS ความถี่คู่ที่มีความแม่นยำสูง (L1 และ L5), GPS + Cellular ในตัวทุกเรือน, Bluetooth 5.3, Ultra Wideband 2, มาตรวัดความลึกพร้อมเซ็นเซอร์วัดอุณหภูมิน้ำ, ไซเรน 86 เดซิเบลได้ยินไกลถึง 180 ม.', 'ตัวเรือนไทเทเนียมเกรดอากาศยาน 95% รีไซเคิล แข็งแกร่ง ทนต่อการกัดกร่อน กันน้ำลึก 100 ม. มาตรฐาน EN13319 สำหรับการดำน้ำลึก 40 ม.', 29900, 33900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-49-titanium-natural-ultra2?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-49-titanium-natural-ultra2?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-watch/apple-watch-ultra', 'https://www.apple.com/th/apple-watch-ultra-2/specs/', 'https://www.apple.com/th/apple-watch-ultra-2/');
INSERT INTO sub_models (id, family_id, category_id, name_th, name_en, screen_size, dimensions_mm, weight_grams, chip, display_specs, camera_specs, battery_specs, box_contents, connectivity, material, min_price_thb, max_price_thb, hero_image_url, hero_image_png, buy_url, specs_url, overview_url) VALUES ('apple-watch-se-40', 'apple-watch-se', 'watch', 'Apple Watch SE (40 มม. / 44 มม.)', 'Apple Watch SE (40mm / 44mm)', '40mm', '40.0 x 34.0 x 10.7 มม. (40mm) / 44.0 x 38.0 x 10.7 มม. (44mm)', '26.4 กรัม (40mm GPS) / 32.9 กรัม (44mm GPS)', 'ชิป S8 SiP พร้อมโปรเซสเซอร์แบบ 64-bit 2-core', 'จอภาพ Retina LTPO OLED ความสว่างสูงสุด 1,000 นิต, กระจกหน้าจอ Ion-X', 'ไม่มีในตัว (รองรับรีโมทควบคุมกล้อง iPhone)', 'แบตเตอรี่ใช้งานได้นานสูงสุด 18 ชั่วโมง', 'Apple Watch SE, สายนาฬิกา, สายชาร์จแบบแม่เหล็กเป็น USB-C (1 ม.)', 'GPS หรือ GPS + Cellular, Wi-Fi, Bluetooth 5.3, การตรวจจับการชนกัน (Crash Detection)', 'ตัวเรือนอะลูมิเนียมรีไซเคิล 100% พร้อมฝาหลังวัสดุคอมโพสิตไนลอนที่เข้าคู่กัน', 7900, 10900, 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-40-aluminum-midnight-nc-se?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-40-aluminum-midnight-nc-se?wid=2048&hei=2048&fmt=png-alpha', 'https://www.apple.com/th/shop/buy-watch/apple-watch-se', 'https://www.apple.com/th/apple-watch-se/specs/', 'https://www.apple.com/th/apple-watch-se/');
