INSERT INTO variants (id, part_number, sub_model_id, product_id, category_id, model_name, color_id, color_th, color_en, color_hex, storage, screen_size, connectivity, specs_chip, dimensions_mm, weight_grams, display_specs, camera_specs, battery_specs, box_contents, material, price_thb, formatted_price, image_url, image_url_png, local_image_path, local_image_png, buy_url, specs_url, overview_url, product_url) VALUES ('TH-IPADPRO11M4-SPACEBLACK-256GBWIF-9979', 'TH-IPADPRO11M4-SPACEBLACK-256GBWIF-9979', 'ipad-pro-11-m4', 'ipad-pro', 'ipad', 'iPad Pro รุ่น 11 นิ้ว (M4) 256GB (Wi-Fi) สีดำสเปซแบล็ค (Space Black)', 'space-black', 'ดำสเปซแบล็ค', 'Space Black', '#2E2C2F', '256GB (Wi-Fi)', '11"', 'Thunderbolt / USB 4 (สูงสุด 40Gb/s), Wi-Fi 6E (802.11ax), Bluetooth 5.3, ตัวเลือก 5G (eSIM)', 'ชิป M4 พร้อม CPU สูงสุดแบบ 10-core, GPU แบบ 10-core รองรับ Ray Tracing ด้วยฮาร์ดแวร์ และ Neural Engine แบบ 16-core (38 ล้านล้านคำสั่งต่อวินาที)', '249.7 x 177.5 x 5.3 มม.', '444 กรัม (Wi-Fi) / 446 กรัม (Cellular)', 'จอภาพ Ultra Retina XDR เทคโนโลยี Tandem OLED สองชั้น, ความละเอียด 2420 x 1668 พิกเซลที่ 264 ppi, ProMotion 10-120Hz, ความสว่างเต็มหน้าจอ 1,000 นิต (XDR สูงสุด 1,600 นิต), ตัวเลือกกระจก Nano-texture สำหรับรุ่น 1TB/2TB', 'กล้องไวด์ 12MP (ƒ/1.8), ซูมดิจิทัล 5x, แฟลช True Tone แบบปรับตามสภาวะ, สแกนเนอร์ LiDAR, กล้องหน้าแนวนอน Ultra Wide 12MP พร้อมคุณสมบัติจัดให้อยู่ตรงกลาง (Center Stage)', 'ท่องเว็บผ่าน Wi-Fi หรือดูวิดีโอนานสูงสุด 10 ชั่วโมง, ชาร์จผ่านอะแดปเตอร์แปลงไฟหรือ USB-C เข้ากับระบบคอมพิวเตอร์', 'iPad Pro 11 นิ้ว, สายชาร์จ USB-C (1 ม.), อะแดปเตอร์แปลงไฟ USB-C ขนาด 20W, ผ้าเช็ดหน้าจอ (เฉพาะรุ่นกระจก Nano-texture)', 'ตัวเครื่องอะลูมิเนียมรีไซเคิล 100% ดีไซน์บางเฉียบที่สุดเท่าที่ Apple เคยสร้างมาเพียง 5.3 มม.', 39900, '฿39,900', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/ipad-pro-finish-select-202405-11inch-spaceblack?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/ipad-pro-finish-select-202405-11inch-spaceblack?wid=2048&hei=2048&fmt=png-alpha', 'data/images/ipad/ipad-pro/space-black.jpg', 'data/images/ipad/ipad-pro/space-black/hero.png', 'https://www.apple.com/th/shop/buy-ipad/ipad-pro', 'https://www.apple.com/th/ipad-pro/specs/', 'https://www.apple.com/th/ipad-pro/', 'https://www.apple.com/th/shop/buy-ipad/ipad-pro');
