INSERT INTO variants (id, part_number, sub_model_id, product_id, category_id, model_name, color_id, color_th, color_en, color_hex, storage, screen_size, connectivity, specs_chip, dimensions_mm, weight_grams, display_specs, camera_specs, battery_specs, box_contents, material, price_thb, formatted_price, image_url, image_url_png, local_image_path, local_image_png, buy_url, specs_url, overview_url, product_url) VALUES ('TH-MACBOOKPRO14-SPACEBLACK-M416GB51-FBCD', 'TH-MACBOOKPRO14-SPACEBLACK-M416GB51-FBCD', 'macbook-pro-14', 'macbook-pro', 'mac', 'MacBook Pro 14 นิ้ว (M4 / M4 Pro / M4 Max) M4 (16GB / 512GB) สีดำสเปซแบล็ค (Space Black)', 'space-black', 'ดำสเปซแบล็ค', 'Space Black', '#2E2C2F', 'M4 (16GB / 512GB)', '14.2"', 'พอร์ต Thunderbolt 4 (M4) หรือ Thunderbolt 5 สูงสุด 120Gb/s (M4 Pro/Max) จำนวน 3 พอร์ต, ช่องเสียบการ์ด SDXC, พอร์ต HDMI รองรับ 8K, ช่องต่อหูฟัง 3.5 มม., พอร์ต MagSafe 3, Wi-Fi 6E, Bluetooth 5.3', 'ชิป M4 (CPU 10-core, GPU 10-core) หรือ M4 Pro (CPU สูงสุด 14-core, GPU สูงสุด 20-core) หรือ M4 Max (CPU สูงสุด 16-core, GPU สูงสุด 40-core)', '312.6 x 221.2 x 15.5 มม.', '1,550 กรัม (M4) / 1,600 กรัม (M4 Pro/Max)', 'จอภาพ Liquid Retina XDR ขนาด 14.2 นิ้ว, ความละเอียด 3024 x 1964 พิกเซลที่ 254 ppi, ProMotion 120Hz, ความสว่าง SDR สูงสุด 1,000 นิต, XDR สูงสุด 1,600 นิต, ตัวเลือกกระจก Nano-texture', 'กล้อง 12MP Center Stage รองรับ Desk View และวิดีโอ 1080p HD, ระบบเสียง 6 ลำโพงพร้อมวูฟเฟอร์ตัดแรงสั่นสะเทือน', 'เล่นวิดีโอนานสูงสุด 24 ชั่วโมง (M4) / สูงสุด 22 ชั่วโมง (M4 Pro/Max), ท่องเว็บแบบไร้สายสูงสุด 16 ชั่วโมง, ชาร์จเร็วผ่านอะแดปเตอร์ 70W หรือ 96W', 'MacBook Pro 14 นิ้ว, สาย USB-C เป็น MagSafe 3 (2 ม.), อะแดปเตอร์แปลงไฟ USB-C ขนาด 70W (สำหรับ M4) หรือ 96W (สำหรับ M4 Pro)', 'ตัวเครื่องอะลูมิเนียมชิ้นเดียว (Unibody) รีไซเคิล 100% พร้อมระบบระบายความร้อนอันล้ำสมัย', 54900, '฿54,900', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mbp14-spaceblack-select-202410?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/mbp14-spaceblack-select-202410?wid=2048&hei=2048&fmt=png-alpha', 'data/images/mac/macbook-pro/space-black.jpg', 'data/images/mac/macbook-pro/space-black/hero.png', 'https://www.apple.com/th/shop/buy-mac/macbook-pro', 'https://www.apple.com/th/macbook-pro/specs/', 'https://www.apple.com/th/macbook-pro/', 'https://www.apple.com/th/shop/buy-mac/macbook-pro');
