INSERT INTO variants (id, part_number, sub_model_id, product_id, category_id, model_name, color_id, color_th, color_en, color_hex, storage, screen_size, connectivity, specs_chip, dimensions_mm, weight_grams, display_specs, camera_specs, battery_specs, box_contents, material, price_thb, formatted_price, image_url, image_url_png, local_image_path, local_image_png, buy_url, specs_url, overview_url, product_url) VALUES ('TH-APPLEWATCHULTRA2-NATURALTITANIUM-TIGPSCEL-7334', 'TH-APPLEWATCHULTRA2-NATURALTITANIUM-TIGPSCEL-7334', 'apple-watch-ultra-2', 'apple-watch-ultra-2', 'watch', 'Apple Watch Ultra 2 (49 มม.) ไทเทเนียม GPS + Cellular (Trail Loop) สีไทเทเนียมธรรมชาติ (Natural Titanium)', 'natural-titanium', 'ไทเทเนียมธรรมชาติ', 'Natural Titanium', '#9A958E', 'ไทเทเนียม GPS + Cellular (Trail Loop)', '49mm', 'GPS ความถี่คู่ที่มีความแม่นยำสูง (L1 และ L5), GPS + Cellular ในตัวทุกเรือน, Bluetooth 5.3, Ultra Wideband 2, มาตรวัดความลึกพร้อมเซ็นเซอร์วัดอุณหภูมิน้ำ, ไซเรน 86 เดซิเบลได้ยินไกลถึง 180 ม.', 'ชิป S9 SiP พร้อมโปรเซสเซอร์ 64-bit แบบ 2-core และ Neural Engine แบบ 4-core, คำสั่งนิ้ว ''แตะสองครั้ง'' (Double Tap)', '49.0 x 44.0 x 14.4 มม.', '61.4 กรัม (ไทเทเนียมธรรมชาติ) / 61.8 กรัม (ไทเทเนียมดำ)', 'จอภาพ Always-On Retina LTPO OLED ความสว่างสูงสุดถึง 3,000 นิต (สว่างที่สุดในบรรดาอุปกรณ์พกพา Apple ทั้งหมด), ความสว่างต่ำสุด 1 นิตในที่มืด, ผลึกแซฟไฟร์แบนเรียบพร้อมขอบยกสูงป้องกันแรงกระแทก', 'ไม่มีในตัว (รองรับรีโมทควบคุมกล้อง iPhone)', 'การใช้งานปกติสูงสุด 36 ชั่วโมง, ในโหมดประหยัดพลังงานสูงสุด 72 ชั่วโมง, ใช้งานกิจกรรมกลางแจ้งพร้อม GPS และวัดอัตราการเต้นของหัวใจสูงสุด 17 ชั่วโมง', 'Apple Watch Ultra 2, สายนาฬิกา (Trail Loop, Alpine Loop, หรือ Ocean Band), สายชาร์จเร็วแบบแม่เหล็กเป็น USB-C แบบถัก (1 ม.)', 'ตัวเรือนไทเทเนียมเกรดอากาศยาน 95% รีไซเคิล แข็งแกร่ง ทนต่อการกัดกร่อน กันน้ำลึก 100 ม. มาตรฐาน EN13319 สำหรับการดำน้ำลึก 40 ม.', 29900, '฿29,900', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-49-titanium-natural-ultra2?wid=2560&hei=2560&fmt=jpeg&qlt=95', 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/watch-case-49-titanium-natural-ultra2?wid=2048&hei=2048&fmt=png-alpha', 'data/images/watch/apple-watch-ultra-2/natural-titanium.jpg', 'data/images/watch/apple-watch-ultra-2/natural-titanium/hero.png', 'https://www.apple.com/th/shop/buy-watch/apple-watch-ultra', 'https://www.apple.com/th/apple-watch-ultra-2/specs/', 'https://www.apple.com/th/apple-watch-ultra-2/', 'https://www.apple.com/th/shop/buy-watch/apple-watch-ultra');
